const hits = [];
for (let r = 2; r <= 21; r++) {
  const t = String(wb.getRange(`Sheet1!E${r}`).getCell().getValue() ?? '');
  if (!t.includes('Check')) continue;
  const nums = t.match(/\d+/g);
  hits.push([r, t, nums]);
  if (nums && nums.length === 1) wb.getRange(`Sheet1!D${r}`).setValue(Number(nums[0]));
  else warn('unexpected', r, t);
}
log(JSON.stringify(hits));
